    inverse relation) come from the single registry in
    :mod:`quantum_circuit.gates` via :attr:`gate`, so every consumer of an
    operation sees the same immutable definition.
    """

    kind: str  # 'x', 'h', 'y', 'z', 's', 'sdg', 't', 'tdg', 'cx', 'cz', 'swap',
