import ast, pathlib, sys
# minimal unused-import check
for f in sorted(pathlib.Path('quantum_circuit').glob('*.py')):
    src = f.read_text()
    tree = ast.parse(src)
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported[a.asname or a.name] = node.lineno
        elif isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name).split('.')[0]] = node.lineno
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | \
            {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)} | \
            {getattr(n.value, 'id', None) for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    for name, line in imported.items():
        base = name.split('.')[0]
        if base not in names and base not in {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}:
            # check attribute roots
            used = any(isinstance(n, ast.Name) and n.id == base for n in ast.walk(tree))
            if not used:
                print(f"{f}:{line}: possibly unused import {name}")
print("import check done")
